  (NULL,'migration 228','systeme','ce_qui_n_est_pas_ecrit_est_dit','pays',0,
   'Les notes de l Equateur nomment les trois ateliers de Guayaquil (une source chacun) ; celles du Costa Rica disent Tabacos de la Cordillera sans domaine ; celles du Mexique disent Don Chicho a une mention ; celles des Philippines disent que rien n a ete trouve au-dela des quatre fiches'),
  (NULL,'migration 228','systeme','vitrines_completees','marque',0,
   'Tabaqueria de Filipinas : 200 personnes et 15 000 cigares par jour (2016). Joyas de Panama : gamme ecrite avec Flor de Panama, reportage de 2025. Costa Rica : tabacaleras reecrits — dix fiches, trois fabriques, plus un seul acteur. Panama : deux fabriques marquees fermees');

SELECT
  (SELECT COUNT(*) FROM `brands` WHERE `name` IN ('IGM Cigars', 'Tabacalera R. Paxtián', 'Cházaro')) = 3 AS trois_fiches,
  (SELECT COUNT(*) FROM `production_zones` WHERE `id` = 55) = 1 AS zone_queretaro,
  (SELECT SUM(`notes_ar` LIKE '%إحصاء 2026%') FROM `producer_countries` WHERE `id` IN ('ecuador','costarica','mexico','philippines')) = 4 AS quatre_notes,
  (SELECT JSON_LENGTH(`gamme_zh`) FROM `brands` WHERE `name` = 'Joyas de Panamá') = 2 AS panama_gamme,
  (SELECT `history_de` LIKE '%Zensus von 2026%' FROM `brands` WHERE `name` = 'Tabaqueria de Filipinas') AS filipinas_completee,
  (SELECT JSON_LENGTH(`tabacaleras`) FROM `producer_countries` WHERE `id` = 'costarica') = 5 AS costarica_cinq;
SELECT COUNT(*) AS marques, SUM(TRIM(COALESCE(`source`,'')) = '') AS sans_source FROM `brands`;
